mapper.select:
SELECT f.id, f.user_id, u.username, f.feedback_type, CASE WHEN f.feedback_type = 0 THEN '建议' WHEN f.feedback_type = 1 THEN '问题' WHEN f.feedback_type = 2 THEN '功能需求' ELSE '未知' END AS feedback_type_name, f.feedback_title, f.feedback_content, f.contact_info, f.submitted_at, f.status, CASE WHEN f.status = 0 THEN '待处理' WHEN f.status = 1 THEN '处理中' WHEN f.status = 2 THEN '已解决' WHEN f.status = 3 THEN '已关闭' ELSE '未知' END AS status_name, f.processed_by, pu.username AS processed_by_name, f.processed_at, f.process_result, CASE WHEN fe.id IS NOT NULL THEN true ELSE false END AS evaluated FROM feedback f LEFT JOIN sys_user u ON f.user_id = u.id LEFT JOIN sys_user pu ON f.processed_by = pu.id LEFT JOIN feedback_evaluation fe ON f.id = fe.feedback_id
AND f.feedback_type = #{feedbackType}
AND f.status = #{status}
AND f.user_id = #{userId}
AND f.processed_by = #{processedBy}
AND (f.feedback_title LIKE CONCAT('%', #{keyword}, '%') OR f.feedback_content LIKE CONCAT('%', #{keyword}, '%'))
AND f.submitted_at >= #{startTime}
AND f.submitted_at <= #{endTime}
ORDER BY f.submitted_at DESC
